#!/usr/bin/env python3
"""
Mahalo Taxi ナビバーロゴ差し替えスクリプト
usage: python3 replace_nav_logo.py index.html
出力: index_new.html
"""
import sys, re

NEW_B64 = ""

def replace_logo(html):
    # base64埋め込みロゴ(PNG or JPEG)を新ロゴに差し替え
    pattern = r'(<div class="nav-logo"><img src=")data:image/[^;]+;base64,[^"]*(")'
    new_tag = r'\1' + "data:image/jpeg;base64," + NEW_B64 + r' alt=\"Mahalo Taxi Logo\" style=\"height:50px;\" \2'
    new_html, n = re.subn(pattern, new_tag, html)
    return new_html, n

if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "index.html"
    with open(path, "r", encoding="utf-8") as f:
        html = f.read()
    new_html, count = replace_logo(html)
    if count == 0:
        print("NG: ナビロゴのパターンが見つかりませんでした")
    else:
        out = path.replace(".html", "_new.html")
        with open(out, "w", encoding="utf-8") as f:
            f.write(new_html)
        print(f"完了: {out} ({count}箇所置換)")
